#include <vector>
#include <unordered_set>
#include <cmath>
#include <algorithm>

class Solution {
public:
    int closestToTarget(std::vector<int>& arr, int target) {
        std::unordered_set<int> curSet;
        int ans = 1e9;
        for (int x : arr) {
            std::unordered_set<int> nextSet;
            nextSet.insert(x);
            ans = std::min(ans, std::abs(x - target));
            for (int v : curSet) {
                int newVal = v & x;
                nextSet.insert(newVal);
                ans = std::min(ans, std::abs(newVal - target));
            }
            curSet = std::move(nextSet);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int closestToTarget(int[] arr, int target) {
        Set<Integer> curSet = new HashSet<>();
        int ans = Integer.MAX_VALUE;
        for (int x : arr) {
            Set<Integer> nextSet = new HashSet<>();
            nextSet.add(x);
            ans = Math.min(ans, Math.abs(x - target));
            for (int v : curSet) {
                int newVal = v & x;
                nextSet.add(newVal);
                ans = Math.min(ans, Math.abs(newVal - target));
            }
            curSet = nextSet;
        }
        return ans;
    }
}

